// biome-ignore-all lint/a11y/useSemanticElements: BreadcrumbPage mirrors shadcn's Base UI markup, which keeps the current page a span and marks it with aria-current instead of rendering a second link.
// biome-ignore-all lint/a11y/useFocusableInteractive: the current page is deliberately not focusable; a tab stop that goes nowhere is worse than the ARIA pattern.
"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { ChevronRight, MoreHorizontal } from "lucide-react";
import { useIsPresent, usePresence } from "motion/react";
import type * as React from "react";
import {
  createContext,
  useContext,
  useEffect,
  useInsertionEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import { type BreadcrumbMember, breadcrumbDestination, createBreadcrumbTrail } from "../lib/breadcrumb-layout";
import { createGroupPositions } from "../lib/button-group-layout";
import { cn } from "../lib/cn";
import { useStateColor } from "../lib/css-motion";
import { createInlineEntrance } from "../lib/inline-entrance";
import { createInlinePresence } from "../lib/inline-presence";
import { createMeasuredGeometry } from "../lib/measured-geometry";
import { bindMotionParameters, geometryCompact } from "../lib/motion";
import {
  createPresentationScope,
  documentPresentation,
  MotionPresentation,
  usePresentationScope,
} from "../lib/motion-presence";
import { type MotionHostRef, useMotionHostRef } from "../lib/motion-ref";
import { createMotionTransaction } from "../lib/motion-transaction";
import { type CadenceMotion, useCadenceMotion } from "../lib/provider";
import { nativeTextContext } from "../lib/text-layout";
import { useTextPresentation } from "../lib/use-text-presentation";

const committed = typeof window === "undefined" ? useEffect : useLayoutEffect;
const subscribe = () => () => {};
type Scope = ReturnType<typeof createPresentationScope>;

/**
 * The trail's committed path: every retained crumb owns its own projection, so the
 * list only publishes measurement and the shared revision.
 */
type Trail = {
  scope: Scope;
  present: boolean;
  members: Map<object, BreadcrumbMember>;
  request(passive?: boolean): void;
  forget(identity: object): void;
};
const TrailContext = createContext<Trail | null>(null);

export interface BreadcrumbProps extends React.ComponentProps<"nav"> {}

/**
 * The path to the current page. The landmark itself is static: its position in the
 * page is navigation, not decoration.
 *
 * a11y: the `nav` is labelled "breadcrumb", so a screen reader lists it as its own
 * landmark. The last crumb is a `BreadcrumbPage` (not a link) marked
 * `aria-current="page"`.
 */
function Breadcrumb({ className, ...props }: BreadcrumbProps) {
  return <nav aria-label="breadcrumb" data-slot="breadcrumb" className={cn(className)} {...props} />;
}

export interface BreadcrumbListProps extends React.ComponentProps<"ol"> {}

/**
 * The surviving owner of one path revision. It measures final crumb boxes once after a
 * committed membership or label change, keeps the path's own block size and never
 * chases a child's interpolated size. Passive viewport/font reflow stays native.
 */
function BreadcrumbList({ className, children, ...props }: BreadcrumbListProps) {
  const { node, ref } = useMotionHostRef<HTMLOListElement>(props.ref);
  const cm = useCadenceMotion(node);
  const parent = usePresentationScope();
  const [scope] = useState(() => createPresentationScope(node));
  const present = useIsPresent();
  const hydrated = useSyncExternalStore(
    subscribe,
    () => false,
    () => true,
  );
  const initialHydration = useRef(hydrated);
  const consumed = useRef(false);
  const entrance = useRef<ReturnType<typeof createInlineEntrance> | null>(null);
  const [owned] = useState(() => {
    const members = new Map<object, BreadcrumbMember>();
    const transaction = createMotionTransaction();
    return { members, transaction, geometry: createMeasuredGeometry(transaction) };
  });
  const trail = useRef<ReturnType<typeof createBreadcrumbTrail> | null>(null);
  const registered = useRef<{ host: HTMLElement; release(): void } | null>(null);
  const latest = useRef({ cm, present, available: true });
  const [trailValue] = useState<Trail>(() => ({
    scope,
    present: true,
    members: owned.members,
    request: (passive) => trail.current?.request(passive),
    forget: (identity) => {
      owned.members.delete(identity);
      trail.current?.forget(identity);
    },
  }));
  useEffect(() => {
    if (!parent && node.current) documentPresentation(node.current.ownerDocument).presented = true;
  }, [parent, node]);
  committed(() => {
    latest.current = { cm, present, available: scope.available() && (!parent || parent.available()) };
    trailValue.present = present;
    const host = node.current;
    if (!host) return;
    if (!entrance.current) entrance.current = createInlineEntrance(host);
    const baseline = parent ?? documentPresentation(host.ownerDocument);
    entrance.current.commit({
      present,
      enter:
        !consumed.current &&
        !initialHydration.current &&
        baseline.presented &&
        baseline.available() &&
        !host.hasAttribute("data-starting-style"),
      cm: nativeTextContext(host) ? { ...cm, timeScale: 0 } : cm,
    });
    consumed.current = true;
    if (registered.current?.host !== host) {
      registered.current?.release();
      registered.current = {
        host,
        release: owned.geometry.register({
          host: node,
          content: host,
          axes: ["height"],
          observeChildren: true,
          measure: () => breadcrumbDestination(host),
        }),
      };
    }
    if (!trail.current)
      trail.current = createBreadcrumbTrail({
        host: node,
        members: owned.members,
        preflight: (visuals) => owned.transaction.preflightVisuals(visuals),
        revision: (signature) => owned.transaction.revision("content", signature, host),
        resize: (revision) => {
          const parameters = latest.current.cm.parameters(
            bindMotionParameters(geometryCompact, "geometry.resize/measured"),
          );
          if (parameters.kind !== "geometry") return;
          owned.geometry.commit(revision, {
            reduced: latest.current.cm.reduced,
            transition: parameters.transition,
            available: latest.current.present && latest.current.available,
          });
        },
      });
    if (present) scope.transaction.open();
    else scope.transaction.close();
    scope.presented = present;
    trail.current.request();
  });
  committed(
    () => () => {
      entrance.current?.dispose();
      entrance.current = null;
      registered.current?.release();
      registered.current = null;
      trail.current?.dispose();
      trail.current = null;
      owned.geometry.dispose();
    },
    [owned],
  );
  const resize = useRef<() => void>(() => {});
  resize.current = () => trail.current?.request(true);
  committed(() => {
    const host = node.current;
    const view = host?.ownerDocument.defaultView;
    const fonts = host?.ownerDocument.fonts;
    const request = () => resize.current();
    view?.addEventListener("resize", request);
    fonts?.addEventListener("loadingdone", request);
    return () => {
      view?.removeEventListener("resize", request);
      fonts?.removeEventListener("loadingdone", request);
    };
  }, [node]);
  return (
    <MotionPresentation scope={scope}>
      <TrailContext.Provider value={trailValue}>
        <ol
          data-slot="breadcrumb-list"
          className={cn(
            "relative flex flex-wrap items-center gap-1.5 text-sm break-words text-muted-foreground sm:gap-2.5",
            className,
          )}
          {...props}
          ref={ref}
          data-motion={cm.mode}
          data-ending-style={present ? undefined : ""}
          aria-hidden={present ? props["aria-hidden"] : true}
          inert={!present || props.inert || undefined}
        >
          {children}
        </ol>
      </TrailContext.Provider>
    </MotionPresentation>
  );
}

/** One retained crumb: its own presence channel, its own projection and - where the
 * part paints its own foreground - its own scoped colour owner. */
function useCrumb(node: MotionHostRef<HTMLElement>, cm: CadenceMotion) {
  const trail = useContext(TrailContext);
  const parent = usePresentationScope();
  const [entity] = useState(() => ({}));
  const [positions] = useState(() => createGroupPositions(trail?.scope.transaction));
  const [member] = useState<BreadcrumbMember>(() => ({
    host: node,
    cm,
    positions,
    present: true,
  }));
  const scope = trail?.scope ?? parent;
  const [present, remove] = usePresence();
  const removal = useRef({ ready: false, pending: false, present, complete: remove });
  useInsertionEffect(() => {
    Object.assign(removal.current, { ready: false, present, complete: remove });
  });
  useEffect(() => {
    const batch = removal.current;
    batch.ready = true;
    if (batch.pending && !batch.present) batch.complete?.();
    batch.pending = false;
  });
  const hydrated = useSyncExternalStore(
    subscribe,
    () => false,
    () => true,
  );
  const initialHydration = useRef(hydrated);
  const consumed = useRef(false);
  const lifecycle = useRef<ReturnType<typeof createInlinePresence> | null>(null);
  const registered = useRef<HTMLElement | null>(null);
  committed(() => {
    const host = node.current;
    if (!host) return;
    if (registered.current !== host) {
      if (registered.current) trail?.forget(entity);
      registered.current = host;
      trail?.members.set(entity, member);
    }
    Object.assign(member, { host: node, cm, positions, present });
    if (!lifecycle.current) lifecycle.current = createInlinePresence(host, scope?.transaction);
    const baseline = parent ?? documentPresentation(host.ownerDocument);
    const available = scope ? scope.available() : baseline.available();
    lifecycle.current.commit({
      present,
      enter:
        !consumed.current &&
        !initialHydration.current &&
        baseline.presented &&
        Boolean(available) &&
        !host.hasAttribute("data-starting-style"),
      cm: nativeTextContext(host) ? { ...cm, timeScale: 0 } : cm,
      complete: () => {
        const delivery = removal.current;
        if (delivery.present) return;
        if (delivery.ready) delivery.complete?.();
        else delivery.pending = true;
      },
    });
    consumed.current = true;
    trail?.request();
  });
  committed(
    () => () => {
      lifecycle.current?.dispose();
      lifecycle.current = null;
      positions.dispose();
      if (registered.current) trail?.forget(entity);
      registered.current = null;
    },
    [entity, positions, trail],
  );
  return {
    present,
    /** A leaving crumb keeps a noninteractive visual at its last committed box. */
    style:
      !present && member.box
        ? ({
            position: "absolute",
            left: member.box.x,
            top: member.box.y,
            width: member.box.width,
          } as const)
        : {},
  };
}

export interface BreadcrumbItemProps extends React.ComponentProps<"li"> {}

function BreadcrumbItem({ className, children, ...props }: BreadcrumbItemProps) {
  const { node, ref } = useMotionHostRef<HTMLLIElement>(props.ref);
  const cm = useCadenceMotion(node);
  const crumb = useCrumb(node, cm);
  return (
    <li
      data-slot="breadcrumb-item"
      className={cn("inline-flex items-center gap-1.5", className)}
      {...props}
      ref={ref}
      data-motion={cm.mode}
      data-ending-style={crumb.present ? undefined : ""}
      aria-hidden={crumb.present ? props["aria-hidden"] : true}
      inert={!crumb.present || props.inert || undefined}
      style={{ ...crumb.style, ...props.style }}
    >
      {children}
    </li>
  );
}

/** A caller palette this owner cannot verify keeps its paint immediate. */
const layoutClass =
  /^(?:[\w-]+:)*(?:w-|h-|size-|min-|max-|p[xytrblse]?-|m[xytrblse]?-|gap-|flex|inline-|block|grid|shrink|grow|basis-|items-|justify-|self-|order-|relative|absolute|fixed|sticky|inset-|top-|bottom-|left-|right-|overflow-|truncate|whitespace-)/;

function knownPalette(className: unknown, style: unknown) {
  if (typeof className === "function" || typeof style === "function") return false;
  const layoutOnly =
    !className ||
    String(className)
      .split(/\s+/)
      .every((name) => layoutClass.test(name));
  const knownStyle =
    !style ||
    !Object.keys(style as object).some((key) =>
      /color|background|fill|stroke|shadow|filter|blend|opacity|^--(?!motion-|cadence-|ease-)/i.test(key),
    );
  return layoutOnly && knownStyle;
}

export interface BreadcrumbLinkProps extends useRender.ComponentProps<"a"> {}

/**
 * `render` (Base UI) is how a client-side router link gets in: pass the router's
 * own link element and keep `data-slot="breadcrumb-link"`.
 *
 * A direct plain label is one owned display host, so only changed graphemes are
 * replaced. Rich children and `render` callbacks keep their own structure.
 */
function BreadcrumbLink({ className, children, render, ...props }: BreadcrumbLinkProps) {
  const { node, ref } = useMotionHostRef<HTMLAnchorElement>(props.ref);
  const cm = useCadenceMotion(node);
  const [entity] = useState(() => ({}));
  const paint = useStateColor(ref, cm, ["color"], {
    readability: "verified",
    immediate: !knownPalette(className, props.style),
  });
  const plain = typeof children === "string" || typeof children === "number";
  return (
    <BreadcrumbLinkHost
      {...props}
      {...paint}
      data-slot="breadcrumb-link"
      data-motion={cm.mode}
      render={render}
      className={cn("hover:text-foreground", className)}
      style={{ ...paint.style, ...props.style }}
    >
      {plain ? <BreadcrumbLinkText value={String(children)} entity={entity} /> : children}
    </BreadcrumbLinkHost>
  );
}

/** Base render adapter: one physical anchor, no wrapper and no second ref. */
function BreadcrumbLinkHost({ className, render, ...props }: BreadcrumbLinkProps) {
  return useRender({
    defaultTagName: "a",
    props: mergeProps<"a">({ className }, props),
    render,
    // `state` is what emits `data-slot` — Base UI converts state keys to data-* attributes.
    state: { slot: "breadcrumb-link" },
  });
}

function BreadcrumbLinkText({ value, entity }: { value: string; entity: object }) {
  const { node, ref } = useMotionHostRef<HTMLSpanElement>();
  const cm = useCadenceMotion(node);
  const text = useTextPresentation(node, value, cm, entity, { characterStagger: false });
  return (
    <span ref={ref} data-slot="breadcrumb-link-text" data-motion={cm.mode}>
      {text}
    </span>
  );
}

export interface BreadcrumbPageProps extends React.ComponentProps<"span"> {}

function BreadcrumbPage({ className, children, ...props }: BreadcrumbPageProps) {
  const { node, ref } = useMotionHostRef<HTMLSpanElement>(props.ref);
  const cm = useCadenceMotion(node);
  const [entity] = useState(() => ({}));
  const paint = useStateColor(ref, cm, ["color"], {
    readability: "verified",
    immediate: !knownPalette(className, props.style),
  });
  const plain = typeof children === "string" || typeof children === "number";
  return (
    <span
      data-slot="breadcrumb-page"
      role="link"
      aria-disabled="true"
      aria-current="page"
      {...props}
      {...paint}
      data-motion={cm.mode}
      className={cn("font-normal text-foreground", className)}
      style={{ ...paint.style, ...props.style }}
    >
      {plain ? <BreadcrumbPageText value={String(children)} entity={entity} /> : children}
    </span>
  );
}

function BreadcrumbPageText({ value, entity }: { value: string; entity: object }) {
  const { node, ref } = useMotionHostRef<HTMLSpanElement>();
  const cm = useCadenceMotion(node);
  const text = useTextPresentation(node, value, cm, entity, { characterStagger: false });
  return (
    <span ref={ref} data-slot="breadcrumb-page-text" data-motion={cm.mode}>
      {text}
    </span>
  );
}

export interface BreadcrumbSeparatorProps extends React.ComponentProps<"li"> {}

function BreadcrumbSeparator({ children, className, ...props }: BreadcrumbSeparatorProps) {
  const { node, ref } = useMotionHostRef<HTMLLIElement>(props.ref);
  const cm = useCadenceMotion(node);
  const crumb = useCrumb(node, cm);
  const paint = useStateColor(ref, cm, ["color"], {
    readability: "verified",
    immediate: !knownPalette(className, props.style),
  });
  return (
    <li
      data-slot="breadcrumb-separator"
      role="presentation"
      aria-hidden="true"
      {...props}
      {...paint}
      data-motion={cm.mode}
      data-ending-style={crumb.present ? undefined : ""}
      inert={!crumb.present || props.inert || undefined}
      className={cn("[&>svg]:size-3.5", className)}
      style={{ ...paint.style, ...crumb.style, ...props.style }}
    >
      {children ?? <ChevronRight />}
    </li>
  );
}

export interface BreadcrumbEllipsisProps extends React.ComponentProps<"span"> {}

/** The collapsed middle of a deep trail; put a `DropdownMenu` trigger beside it. */
function BreadcrumbEllipsis({ className, ...props }: BreadcrumbEllipsisProps) {
  const { node, ref } = useMotionHostRef<HTMLSpanElement>(props.ref);
  const cm = useCadenceMotion(node);
  const crumb = useCrumb(node, cm);
  const paint = useStateColor(ref, cm, ["color"], {
    readability: "verified",
    immediate: !knownPalette(className, props.style),
  });
  return (
    <span
      data-slot="breadcrumb-ellipsis"
      role="presentation"
      aria-hidden="true"
      {...props}
      {...paint}
      data-motion={cm.mode}
      data-ending-style={crumb.present ? undefined : ""}
      inert={!crumb.present || props.inert || undefined}
      className={cn("flex size-9 items-center justify-center", className)}
      style={{ ...paint.style, ...crumb.style, ...props.style }}
    >
      <MoreHorizontal className="size-4" />
      <span className="sr-only">More</span>
    </span>
  );
}

export {
  Breadcrumb,
  BreadcrumbEllipsis,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
};

"use client";

import type { createGroupPositions, GroupPosition } from "./button-group-layout";
import { type GeometryDestination, naturalGeometry } from "./measured-geometry";
import { motionLimits } from "./motion";
import type { MotionHostRef } from "./motion-ref";
import type { MotionRevision } from "./motion-transaction";
import type { CadenceMotion } from "./provider";
import { nativeTextContext } from "./text-layout";

export type BreadcrumbBox = GroupPosition;
export type BreadcrumbRequest = (passive?: boolean) => void;
type Positions = ReturnType<typeof createGroupPositions>;
type Revision = (signature: string) => MotionRevision;

/** One retained crumb. It owns its own projection controller, so the transform stays
 * a local action of the part that carries the crumb. */
export type BreadcrumbMember = {
  host: MotionHostRef<HTMLElement>;
  cm: CadenceMotion;
  positions: Positions;
  present: boolean;
  /** The last committed box: a leaving crumb keeps a noninteractive visual there. */
  box?: BreadcrumbBox | null;
};

/**
 * One committed path revision. The surviving list measures final crumb boxes once and
 * every surviving crumb projects from its own previous box. The trail never writes a
 * crumb's transform, never measures while a projection is in flight and never renders a
 * hidden measurement copy, so one path change has one projection per real crumb.
 *
 * Passive reflow (viewport, font, scrollbar) settles positions and is never mistaken for
 * a caller path revision; a crumb whose destination changed under the same retained node
 * settles instead of morphing into a different destination.
 */
export function createBreadcrumbTrail(input: {
  host: MotionHostRef<HTMLElement>;
  members: Map<object, BreadcrumbMember>;
  preflight: (visuals: ReadonlySet<object>) => boolean;
  revision: Revision;
  /** The list's owned size follows the same committed revision. */
  resize: (revision: MotionRevision) => void;
}) {
  let alive = true;
  let queued = false;
  let passive = false;
  let baseline = "";
  const destinations = new Map<object, string | null>();
  const request: BreadcrumbRequest = (isPassive = false) => {
    passive ||= isPassive;
    if (queued) return;
    queued = true;
    queueMicrotask(() => {
      queued = false;
      const next = passive;
      passive = false;
      if (alive) flush(next);
    });
  };
  const retained = () =>
    [...input.members.entries()]
      .filter(([, member]) => {
        const node = member.host.current;
        return member.present && node?.isConnected && node.parentElement === input.host.current;
      })
      .sort((a, b) => {
        const first = a[1].host.current as HTMLElement;
        const second = b[1].host.current as HTMLElement;
        return first.compareDocumentPosition(second) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1;
      });
  const flush = (isPassive: boolean) => {
    if (!alive) return;
    const list = input.host.current;
    if (!list) return;
    const entries = retained();
    // Bound the projection before measuring or allocating per-member work.
    const bounded =
      entries.length <= motionLimits.collectionVisuals &&
      input.preflight(new Set([list, ...entries.map(([, member]) => member.host.current as HTMLElement)]));
    // Sample a live flight first: the origin is the presentation the reader currently
    // sees, and cancelling it restores native layout for the measurement below.
    const origins = new Map<object, BreadcrumbBox | null>(
      [...input.members.entries()].map(([identity, member]) => {
        const node = member.host.current;
        return [identity, node ? (member.positions.prepare().get(node) ?? null) : null];
      }),
    );
    const rect = list.getBoundingClientRect();
    const boxes = new Map<object, BreadcrumbBox>();
    for (const [identity, member] of entries) {
      const node = member.host.current as HTMLElement;
      const box = node.getBoundingClientRect();
      const measured = { x: box.left - rect.left, y: box.top - rect.top, width: box.width, height: box.height };
      boxes.set(identity, measured);
      member.box = measured;
    }
    const signature = JSON.stringify(
      entries.map(([, member]) => {
        const node = member.host.current as HTMLElement;
        return [node.getAttribute("data-slot"), (node.textContent ?? "").slice(0, 120), node.childElementCount];
      }),
    );
    const semantic = baseline !== "" && signature !== baseline;
    baseline = signature;
    // A retained node that now points elsewhere is a new identity, not a morph.
    const identity = new Map<object, boolean>();
    for (const [key, member] of entries) {
      const destination = crumbDestination(member.host.current as HTMLElement);
      identity.set(key, !destinations.has(key) || destinations.get(key) === destination);
      destinations.set(key, destination);
    }
    const revision = input.revision(signature);
    input.resize(revision);
    // One wrapped row keeps retained positions. A path that moves a crumb between rows
    // settles positions and lets the owned height carry that revision instead.
    const row = entries.every(([key]) => {
      const to = boxes.get(key);
      const from = origins.get(key);
      return !from || !to || Math.abs(to.y - from.y) < 1;
    });
    // Every live crumb keeps its own projection on the newest revision - a retained one
    // may animate, a leaving one settles at its last committed box - so no part holds a
    // stale revision after another crumb left the path.
    const available = bounded && !isPassive && semantic && row && !list.hasAttribute("data-ending-style");
    for (const [key, member] of input.members.entries()) {
      const node = member.host.current;
      if (!node?.isConnected) continue;
      const retained = boxes.has(key);
      const to = boxes.get(key) ?? member.box;
      if (!to) continue;
      member.positions.commit({
        host: member.host,
        revision,
        cm: member.cm,
        boxes: new Map([[node, to]]),
        from: new Map([[node, retained ? (origins.get(key) ?? to) : to]]),
        // A reuse of one label for another destination keeps native layout.
        available: retained && available && identity.get(key) === true && !member.cm.reduced,
        axis: "x",
      });
    }
  };
  return {
    request,
    flush,
    forget(identity: object) {
      destinations.delete(identity);
    },
    dispose() {
      alive = false;
      queued = false;
      passive = false;
      baseline = "";
      destinations.clear();
    },
  };
}

/** The destination a crumb points at, when it has one. Labels are not identity. */
function crumbDestination(node: HTMLElement) {
  const link = node.matches("a[href]") ? node : node.querySelector("a[href]");
  return link ? link.getAttribute("href") : null;
}

/** Known-content height of the wrapping trail: native auto height, no caller dimension
 * engine and no continuous rewrap. Anything unresolved stays native. */
export function breadcrumbDestination(host: HTMLElement): GeometryDestination | null {
  if (nativeTextContext(host)) return null;
  const view = host.ownerDocument.defaultView;
  const css = view?.getComputedStyle(host);
  const box = naturalGeometry(host);
  if (!view || !css || !box || !(box.height > 0)) return null;
  if (!["auto", "fit-content", "max-content"].includes(host.computedStyleMap?.().get("height")?.toString() ?? ""))
    return null;
  if (css.aspectRatio !== "auto" || !css.display.includes("flex") || css.flexWrap !== "wrap") return null;
  const parts = Array.from(host.children);
  if (!parts.length || parts.length > motionLimits.collectionVisuals) return null;
  let depth = 0;
  for (let ancestor: HTMLElement | null = host; ancestor; ancestor = ancestor.parentElement) {
    if (++depth > motionLimits.collectionVisuals) return null;
    const style = view.getComputedStyle(ancestor);
    if (
      style.rotate !== "none" ||
      style.perspective !== "none" ||
      style.transform.startsWith("matrix3d") ||
      (style.scale !== "none" && style.scale.split(/\s+/).some((value) => !(Number.parseFloat(value) > 0)))
    )
      return null;
    if (style.transform !== "none") {
      if (typeof DOMMatrixReadOnly === "undefined") return null;
      const matrix = new DOMMatrixReadOnly(style.transform);
      if (matrix.b !== 0 || matrix.c !== 0 || matrix.a <= 0 || matrix.d <= 0) return null;
    }
  }
  const family = css.transitionProperty.split(",").map((value) => value.trim());
  const durations = css.transitionDuration.split(",").map(Number.parseFloat);
  if (
    family.some(
      (property, index) => ["all", "height"].includes(property) && (durations[index % durations.length] ?? 0) > 0,
    ) ||
    host
      .getAnimations()
      .some((animation) =>
        (animation.effect as KeyframeEffect | null)?.getKeyframes().some((frame) => "height" in frame),
      )
  )
    return null;
  const rect = host.getBoundingClientRect();
  const scale = rect.height / host.offsetHeight;
  if (!Number.isFinite(scale) || scale <= 0) return null;
  // The final wrapped row must stay fully readable while the host is still smaller.
  const required = Math.max(0, ...parts.map((part) => (part.getBoundingClientRect().bottom - rect.top) / scale));
  let max = Number.POSITIVE_INFINITY;
  const parent = host.parentElement;
  const parentCss = parent ? view.getComputedStyle(parent) : null;
  if (parent && parentCss && /^(hidden|clip)$/.test(parentCss.overflowY)) {
    max = (parent.getBoundingClientRect().bottom - rect.top) / scale;
    if (!Number.isFinite(max) || max < box.height) return null;
  }
  return { height: { size: box.height, min: Math.min(box.height, required), max, readable: true, independent: true } };
}

"use client";

import { animateSingleValue, motionValue } from "motion/react";
import { labelGeometry } from "./label-layout";
import { bindMotionParameters, layoutCompact, motionLimits } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import type { MotionHostRef } from "./motion-ref";
import {
  createMotionTransaction,
  knownTextGeometry,
  type MotionLease,
  type MotionRevision,
  registerTextGeometry,
} from "./motion-transaction";
import type { CadenceMotion } from "./provider";

export type GroupPosition = { x: number; y: number; width: number; height: number; velocity?: number };

/** One scalar projection, separate from the control's native host/press layer.
 * The adapter supplies final boxes once; scalar callbacks never read layout. */
export function createGroupPositions(transaction = createMotionTransaction()) {
  const phase = motionValue(1);
  let target = new Map<HTMLElement, GroupPosition>();
  let origin = new Map<HTMLElement, GroupPosition>();
  const effects = new Map<HTMLElement, { animation: Animation; lease: MotionLease; dispose(): void }>();
  let revision: MotionRevision | null = null;
  let clock = "";
  let axis: "x" | "y" = "x";
  const sample = () =>
    new Map(
      [...target].map(([host, box]) => {
        const before = origin.get(host) ?? box;
        const p = Math.max(0, Math.min(1, phase.get()));
        return [
          host,
          {
            ...box,
            x: axis === "x" ? before.x + (box.x - before.x) * p : box.x,
            y: axis === "y" ? before.y + (box.y - before.y) * p : box.y,
            velocity: (box[axis] - before[axis]) * phase.getVelocity(),
          },
        ];
      }),
    );
  const cancel = () => {
    phase.stop();
    const previous = [...effects.values()];
    effects.clear();
    for (const effect of previous) effect.dispose();
  };
  const write = () => {
    const current = sample();
    for (const [host, effect] of effects) {
      const box = current.get(host),
        end = target.get(host);
      if (box && end && effect.lease.current())
        (effect.animation.effect as KeyframeEffect).setKeyframes({
          transform: `translate(${box.x - end.x}px,${box.y - end.y}px)`,
        });
    }
  };
  const off = phase.on("change", write);
  let unsubscribe = () => {};
  return {
    owns(animation: Animation) {
      return [...effects].some(
        ([host, effect]) =>
          effect.animation === animation &&
          effect.lease.current() &&
          (animation.effect as KeyframeEffect | null)?.target === host &&
          knownTextGeometry(animation, "full"),
      );
    },
    prepare() {
      const current = sample();
      cancel();
      return current;
    },
    commit(input: {
      host: MotionHostRef<HTMLElement>;
      revision: MotionRevision;
      cm: CadenceMotion;
      boxes: Map<HTMLElement, GroupPosition>;
      from: Map<HTMLElement, GroupPosition>;
      available: boolean;
      axis: "x" | "y";
    }) {
      const parameters = input.cm.parameters(bindMotionParameters(layoutCompact, "layout.move/position"));
      if (parameters.kind !== "layout") return;
      const nextClock = JSON.stringify([input.cm.mode, parameters.transition]);
      const same = revision === input.revision;
      const changedClock = clock !== nextClock;
      revision = input.revision;
      clock = nextClock;
      cancel();
      target = input.boxes;
      origin = input.from;
      axis = input.axis;
      unsubscribe();
      unsubscribe = input.host.current
        ? subscribeMotionEnvironment(input.host.current.ownerDocument, (environment) => {
            if (environment.hidden || environment.reduced || environment.immediate) {
              cancel();
              origin = target;
            }
          })
        : () => {};
      const visuals = new Set([...(input.host.current ? [input.host.current] : []), ...target.keys()]);
      if (
        !input.available ||
        input.cm.reduced ||
        parameters.transition.duration === 0 ||
        (same && !changedClock) ||
        !transaction.preflightVisuals(visuals)
      ) {
        origin = target;
        return;
      }
      for (const [host, box] of target) {
        const before = origin.get(host);
        if (!before || before[input.axis] === box[input.axis] || !host.animate) continue;
        const owner = transaction.register(host);
        const lease = owner.begin(input.revision, ["transform"], { collectionVisuals: visuals }, cancel);
        if (!lease) {
          owner.dispose();
          cancel();
          return;
        }
        const animation = host.animate({}, { duration: 0, fill: "both" });
        registerTextGeometry(animation, lease, input.cm.mode);
        effects.set(host, {
          animation,
          lease,
          dispose() {
            animation.cancel();
            lease.cancel();
            owner.dispose();
          },
        });
      }
      phase.jump(0);
      write();
      const rates = [...target].flatMap(([host, box]) => {
        const before = origin.get(host),
          delta = box[axis] - (before?.[axis] ?? box[axis]);
        return delta ? [(before?.velocity ?? 0) / delta] : [];
      });
      const rate = rates[0] ?? 0;
      const coherent = rates.every(
        (value) => Math.abs(value - rate) <= Number.EPSILON * Math.max(1, Math.abs(value), Math.abs(rate)),
      );
      if (effects.size)
        animateSingleValue(phase, 1, {
          ...parameters.transition,
          velocity: coherent ? Math.max(0, rate) : 0,
          onComplete: cancel,
        });
    },
    settle() {
      cancel();
      origin = target;
    },
    dispose() {
      cancel();
      off();
      unsubscribe();
      target.clear();
      origin.clear();
    },
  };
}

/** Exact cross-axis native stretch, caused by this scope's leased direct rule.
 * Neither a matching attribute nor an unrelated dimension engine grants it. */
export function groupStretchEcho(
  host: HTMLElement,
  source: HTMLElement,
  target: HTMLElement,
  axis: "width" | "height",
  owns: (animation: Animation) => boolean,
) {
  if (source.parentElement !== host || (target !== host && target.parentElement !== host)) return false;
  const parent = getComputedStyle(host),
    css = getComputedStyle(source);
  if (
    !parent.display.includes("flex") ||
    !(
      (parent.flexDirection.startsWith("row") && axis === "height") ||
      (parent.flexDirection.startsWith("column") && axis === "width")
    )
  )
    return false;
  const vertical = axis === "height";
  const content =
    (vertical ? host.clientHeight : host.clientWidth) -
    Number.parseFloat(parent[vertical ? "paddingTop" : "paddingLeft"]) -
    Number.parseFloat(parent[vertical ? "paddingBottom" : "paddingRight"]);
  const extent =
    (vertical ? source.offsetHeight : source.offsetWidth) +
    Number.parseFloat(css[vertical ? "marginTop" : "marginLeft"]) +
    Number.parseFloat(css[vertical ? "marginBottom" : "marginRight"]);
  if (!Number.isFinite(content) || !Number.isFinite(extent) || Math.round(content) !== Math.round(extent)) return false;
  if (target === host) return true;
  const child = getComputedStyle(target);
  const alignment = child.alignSelf === "auto" ? parent.alignItems : child.alignSelf;
  if (
    target.dataset.slot !== "button-group-segment" ||
    target.computedStyleMap?.().get(axis)?.toString() !== "auto" ||
    alignment !== "stretch" ||
    ["absolute", "fixed"].includes(child.position)
  )
    return false;
  const expected =
    content -
    Number.parseFloat(child[vertical ? "marginTop" : "marginLeft"]) -
    Number.parseFloat(child[vertical ? "marginBottom" : "marginRight"]);
  if (!Number.isFinite(expected) || Math.round(expected) !== (vertical ? target.offsetHeight : target.offsetWidth))
    return false;
  const handles = target.getAnimations();
  return (
    handles.length <= motionLimits.collectionVisuals &&
    handles.every((animation) => {
      if (owns(animation)) return true;
      const frames = (animation.effect as KeyframeEffect | null)?.getKeyframes() ?? [];
      return (
        frames.length <= motionLimits.collectionVisuals &&
        frames.every(
          (frame) =>
            !Object.keys(frame).some((key) =>
              /^(?:width|height|minWidth|maxWidth|minHeight|maxHeight|flexBasis|transform|translate|scale|rotate|padding|gap)$/.test(
                key,
              ),
            ),
        )
      );
    })
  );
}

/** Fixed outgoing paint and local FLIP share a proven untransformed mapping.
 * Caller/native geometry engines are audited by the committed constraint owner. */
export function groupMapping(host: HTMLElement) {
  let count = 0;
  for (let node: HTMLElement | null = host; node; node = node.parentElement) {
    if (++count > motionLimits.collectionVisuals) return false;
    const css = getComputedStyle(node);
    if (
      css.transform !== "none" ||
      css.translate !== "none" ||
      css.rotate !== "none" ||
      css.scale !== "none" ||
      css.perspective !== "none" ||
      css.offsetPath !== "none" ||
      !["normal", "1"].includes(css.zoom) ||
      css.writingMode !== "horizontal-tb"
    )
      return false;
  }
  return true;
}

export function buttonGroupGeometry(
  host: HTMLElement,
  orientation: string,
  clips?: Map<HTMLElement, { width: number; height: number }>,
) {
  const axis = orientation === "vertical" ? "height" : "width";
  if (host.children.length + 1 > motionLimits.collectionVisuals) return null;
  for (const layer of host.children) {
    if (layer.hasAttribute("data-ending-style")) continue;
    const member = layer.firstElementChild;
    for (const node of [layer, member]) {
      if (!(node instanceof HTMLElement)) continue;
      const css = getComputedStyle(node);
      const properties = css.transitionProperty.split(",").map((name) => name.trim());
      const times = css.transitionDuration.split(",").map(Number.parseFloat);
      const dimensional = /^(all|width|height|min-width|max-width|min-height|max-height|padding|gap|flex-basis)$/;
      if (
        properties.some((name, index) => dimensional.test(name) && (times[index % times.length] ?? 0) > 0) ||
        node
          .getAnimations()
          .some(
            (animation) =>
              !knownTextGeometry(animation, "full") &&
              (animation.effect as KeyframeEffect | null)
                ?.getKeyframes()
                .some((frame) =>
                  Object.keys(frame).some((name) =>
                    /^(width|height|minWidth|maxWidth|minHeight|maxHeight|padding|gap|flexBasis)$/.test(name),
                  ),
                ),
          )
      )
        return null;
    }
    if (layer instanceof HTMLElement) {
      const size = layer.computedStyleMap?.().get(axis)?.toString() ?? layer.style[axis];
      if (size && !/^(auto|none|fit-content|max-content|min-content|0|(?:\d+(?:\.\d+)?|\.\d+)px)$/.test(size))
        return null;
    }
  }
  const value = labelGeometry(host, host, true);
  if (!value) return null;
  const target = value[axis];
  if (!target) return null;
  // A shrink-wrapped parent's current extent echoes this very group. It is
  // not an independent maximum that may truncate the captured shrink origin.
  // Actual native min/max constraints remain authoritative over the overlay.
  const constraints = [`min-${axis}`, `max-${axis}`].map(
    (name) => host.computedStyleMap?.().get(name)?.toString() ?? host.style.getPropertyValue(name),
  );
  if (constraints.some((value) => value && !/^(none|auto|0|(?:\d+(?:\.\d+)?|\.\d+)px)$/.test(value))) return null;
  const maximum = constraints[1];
  let clipped = false;
  const box = host.getBoundingClientRect();
  const nextClips = new Map<HTMLElement, { width: number; height: number }>();
  for (let node: HTMLElement | null = host; node; node = node.parentElement) {
    const css = getComputedStyle(node);
    if (!/(hidden|clip|auto|scroll)/.test(`${css.overflowX} ${css.overflowY}`) && !css.contain.includes("paint"))
      continue;
    const clip = node.getBoundingClientRect(),
      before = clips?.get(node);
    nextClips.set(node, { width: clip.width, height: clip.height });
    // A before/after native allocation receipt distinguishes a fixed outer
    // preview/viewport clip from an intrinsic clip that echoes this group.
    // The group shell itself must never introduce an intermediate clip.
    clipped ||=
      node === host ||
      before?.[axis] !== clip[axis] ||
      box.left < clip.left ||
      box.right > clip.right ||
      box.top < clip.top ||
      box.bottom > clip.bottom;
  }
  if (clips) {
    clips.clear();
    for (const [node, box] of nextClips) clips.set(node, box);
  }
  const minimum = constraints[0]?.endsWith("px") ? Number.parseFloat(constraints[0]) : 0;
  return {
    [axis]: {
      ...target,
      min: Math.max(minimum, clipped ? (target.min ?? target.size) : 0),
      max: maximum?.endsWith("px") ? Number.parseFloat(maximum) : undefined,
    },
  };
}

"use client";

import { type GeometryDestination, naturalGeometry } from "./measured-geometry";
import { motionLimits } from "./motion";
import { knownTextGeometry } from "./motion-transaction";
import { nativeTextContext, selectedTextContext } from "./text-layout";

/** Passive constraints are distinct from a committed display revision. */
export function observeLabelConstraints(host: HTMLElement, content: HTMLElement, settle: () => void) {
  const view = host.ownerDocument.defaultView;
  const chain: HTMLElement[] = [];
  for (
    let node: HTMLElement | null = host;
    node && chain.length < motionLimits.collectionVisuals;
    node = node.parentElement
  )
    chain.push(node);
  let parent = host.parentElement;
  while (parent && getComputedStyle(parent).display === "contents") parent = parent.parentElement;
  let alive = true,
    ready = false,
    signature = "",
    width = 0,
    vertical = false;
  let frame: number | null = null;
  const dimension =
    /^(?:all|width|height|min-width|max-width|min-height|max-height|transform|translate|scale|rotate|padding|gap)$/;
  const paint =
    /^(?:color|background|border.*color|box-shadow|text-shadow|opacity|filter|fill|stroke|transition|--(?:cadence-|motion-|ease-))/;
  const read = () =>
    JSON.stringify(
      chain.map((node) => {
        const geometryClock = node.style.transitionProperty.split(",").some((name) => dimension.test(name.trim()));
        return [
          node.className,
          node.hidden,
          node.dir,
          node.getAttribute("contenteditable"),
          node.hasAttribute("inert"),
          node.getAttribute("aria-hidden"),
          Array.from(node.style)
            .filter((name) => !paint.test(name) || (geometryClock && name.startsWith("transition")))
            .map((name) => [name, node.style.getPropertyValue(name)]),
        ];
      }),
    );
  const refresh = () => {
    signature = read();
    width = parent?.getBoundingClientRect().width ?? 0;
    vertical = !!parent && /^(vertical|sideways)/.test(getComputedStyle(parent).writingMode);
    mutations.takeRecords();
    ready = true;
  };
  const cancel = () => {
    if (!alive) return;
    settle();
    refresh();
    if (frame !== null) view?.cancelAnimationFrame(frame);
    frame = null;
  };
  const mutations = new MutationObserver(() => {
    if (alive && ready && signature !== read()) cancel();
  });
  for (const node of chain)
    mutations.observe(node, {
      attributes: true,
      attributeFilter: ["class", "style", "hidden", "dir", "contenteditable", "inert", "aria-hidden"],
    });
  const resize = new ResizeObserver((entries) => {
    if (!alive || !ready || !parent) return;
    const box = entries.find((entry) => entry.target === parent)?.borderBoxSize?.[0];
    if (!box || (vertical ? box.blockSize : box.inlineSize) !== width) cancel();
  });
  if (parent) resize.observe(parent, { box: "border-box" });
  const audit = () => {
    frame = null;
    if (!alive) return;
    const handles = [host, content].flatMap((node) => node.getAnimations?.() ?? []);
    const owned = handles.some((animation) => knownTextGeometry(animation, "full"));
    if (!owned) return;
    const unsafe =
      handles.length > motionLimits.collectionVisuals ||
      handles.some((animation) => {
        if (knownTextGeometry(animation, "full")) return false;
        const keys = (animation.effect as KeyframeEffect | null)?.getKeyframes() ?? [];
        return (
          keys.length > motionLimits.collectionVisuals ||
          keys.some((key) =>
            Object.keys(key).some((name) =>
              dimension.test(name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)),
            ),
          )
        );
      });
    if (unsafe) {
      cancel();
      return;
    }
    frame = view?.requestAnimationFrame(audit) ?? null;
  };
  return {
    prepare(semantic: boolean) {
      if (!semantic && ready && signature !== read()) cancel();
    },
    commit() {
      refresh();
      if (frame === null) audit();
    },
    dispose() {
      alive = false;
      mutations.disconnect();
      resize.disconnect();
      if (frame !== null) view?.cancelAnimationFrame(frame);
    },
  };
}

/** Measure one real label at destination width; never size interactive rich content. */
export function labelGeometry(host: HTMLElement, content: HTMLElement, focusSafe = false): GeometryDestination | null {
  const css = getComputedStyle(host),
    typed = host.computedStyleMap?.();
  const natural = naturalGeometry(host);
  const box = host.getBoundingClientRect();
  if (
    !natural ||
    css.boxSizing !== "border-box" ||
    nativeTextContext(host) ||
    host.closest('[hidden],[inert],[aria-hidden="true"]') ||
    selectedTextContext(host) ||
    (!focusSafe && host.contains(host.ownerDocument.activeElement)) ||
    css.writingMode !== "horizontal-tb" ||
    !["flex", "inline-flex", "block", "inline-block"].includes(css.display)
  )
    return null;
  let parent = host.parentElement;
  while (parent && getComputedStyle(parent).display === "contents") parent = parent.parentElement;
  const parentCSS = parent && getComputedStyle(parent);
  // Percentage/ratio and horizontal flex allocations keep their native owner.
  if (css.aspectRatio !== "auto" || (parentCSS?.display.includes("flex") && parentCSS.flexDirection.startsWith("row")))
    return null;
  const width = typed?.get("width")?.toString();
  const height = typed?.get("height")?.toString();
  const crossAlignment = css.alignSelf === "auto" ? parentCSS?.alignItems : css.alignSelf;
  const intrinsicColumn =
    parentCSS?.display.includes("flex") &&
    parentCSS.flexDirection.startsWith("column") &&
    crossAlignment &&
    !["normal", "stretch"].includes(crossAlignment);
  const intrinsicWidth =
    width === "fit-content" ||
    width === "max-content" ||
    (width === "auto" && (css.display.startsWith("inline-") || intrinsicColumn));
  let clipped = false;
  for (let node: HTMLElement | null = content, depth = 0; node; node = node.parentElement, depth++) {
    if (depth >= motionLimits.collectionVisuals) return null;
    const style = getComputedStyle(node);
    const properties = style.transitionProperty.split(",").map((property) => property.trim());
    const times = style.transitionDuration.split(",").map(Number.parseFloat);
    if (
      properties.some(
        (property, index) =>
          /^(all|width|height|min-width|max-width|min-height|max-height|transform|translate|scale|rotate|padding|gap)$/.test(
            property,
          ) && (times[index % times.length] ?? 0) > 0,
      )
    )
      return null;
    if (
      node
        .getAnimations()
        .some(
          (animation) =>
            !knownTextGeometry(animation, "full") &&
            (animation.effect as KeyframeEffect | null)
              ?.getKeyframes()
              .some((frame) =>
                Object.keys(frame).some((key) =>
                  /^(width|height|minWidth|maxWidth|minHeight|maxHeight|transform|translate|scale|rotate|padding|gap)$/.test(
                    key,
                  ),
                ),
              ),
        )
    )
      return null;
    if (style.scale !== "none" || style.rotate !== "none" || !["normal", "1"].includes(style.zoom)) return null;
    if (style.transform !== "none") {
      const matrix = new DOMMatrixReadOnly(style.transform);
      if (!matrix.is2D || matrix.a !== 1 || matrix.d !== 1 || matrix.b !== 0 || matrix.c !== 0) return null;
    }
    if (/(hidden|clip|auto|scroll)/.test(`${style.overflowX} ${style.overflowY}`) || style.contain.includes("paint"))
      clipped = true;
  }
  const contentBox = naturalGeometry(content);
  if (getComputedStyle(content).boxSizing !== "border-box") return null;
  if (!contentBox) return null;
  const destination: GeometryDestination = {};
  // Growing paint remains fully visible only in existing visible overflow.
  if (intrinsicWidth)
    destination.width = {
      size: box.width,
      min: clipped ? box.width : 0,
      max: Math.max(box.width, parent ? (naturalGeometry(parent)?.width ?? box.width) : box.width),
      readable: true,
      independent: true,
    };
  if (height === "auto")
    destination.height = {
      size: box.height,
      min: box.height,
      max: Math.max(box.height, host.ownerDocument.defaultView?.innerHeight ?? box.height),
      readable: true,
      independent: true,
    };
  return destination;
}

type Interval = [number, number];
const contexts = new WeakMap<Document, CanvasRenderingContext2D>();

/** Prove the complete neutral foreground path over its actual static backdrop.
 * Unknown colour spaces, caller surfaces and parent colour owners stay immediate. */
export function labelColourReadable(node: Element) {
  const view = node.ownerDocument.defaultView;
  if (!view || typeof view.CanvasRenderingContext2D === "undefined") return false;
  let context = contexts.get(node.ownerDocument);
  if (!context) {
    const canvas = node.ownerDocument.createElement("canvas");
    canvas.width = canvas.height = 1;
    context = canvas.getContext("2d", { willReadFrequently: true }) ?? undefined;
    if (!context) return false;
    contexts.set(node.ownerDocument, context);
  }
  const neutral = (value: string) => {
    if (!view.CSS.supports("color", value)) return null;
    context.clearRect(0, 0, 1, 1);
    context.fillStyle = value;
    context.fillRect(0, 0, 1, 1);
    const [r = 0, g = 0, b = 0, a = 0] = context.getImageData(0, 0, 1, 1).data;
    return a && Math.max(r, g, b) !== Math.min(r, g, b) ? null : { value: r / 255, alpha: a / 255 };
  };
  const ancestry: Element[] = [];
  for (let current: Element | null = node; current; current = current.parentElement) {
    if (ancestry.length >= motionLimits.collectionVisuals) return false;
    const css = view.getComputedStyle(current);
    if (css.backgroundImage !== "none" || css.opacity !== "1" || css.filter !== "none" || css.mixBlendMode !== "normal")
      return false;
    if (current !== node && current.getAttribute("data-cadence-color")?.split(",").includes("color")) return false;
    if (
      current !== node &&
      current
        .getAnimations()
        .some((animation) =>
          (animation.effect as KeyframeEffect | null)
            ?.getKeyframes()
            .some((frame) => "backgroundColor" in frame || "color" in frame),
        )
    )
      return false;
    ancestry.push(current);
  }
  let surface: number | null = null;
  for (const current of ancestry.reverse()) {
    const colour = neutral(view.getComputedStyle(current).backgroundColor);
    if (!colour) return false;
    if (surface === null && colour.alpha !== 1) {
      if (colour.alpha === 0) continue;
      return false;
    }
    surface = colour.value * colour.alpha + (surface ?? 0) * (1 - colour.alpha);
  }
  if (surface === null) return false;
  const values = [view.getComputedStyle(node).color];
  for (const animation of node.getAnimations()) {
    if (!("transitionProperty" in animation) || animation.transitionProperty !== "color") continue;
    for (const frame of (animation.effect as KeyframeEffect | null)?.getKeyframes() ?? [])
      if (typeof frame.color === "string") values.push(frame.color);
  }
  const inks: number[] = [];
  for (const value of new Set(values)) {
    const colour = neutral(value);
    if (!colour) return false;
    inks.push(colour.value * colour.alpha + surface * (1 - colour.alpha));
  }
  const interval: Interval = [Math.min(...inks), Math.max(...inks)];
  if (interval[0] <= surface && interval[1] >= surface) return false;
  const luminance = (value: number) => (value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4);
  const low = luminance(interval[1] < surface ? interval[1] : surface);
  const high = luminance(interval[1] < surface ? surface : interval[0]);
  return (high + 0.05) / (low + 0.05) >= 4.5;
}

"use client";

import { bindMotionParameters, motionMilliseconds, presenceInline } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import { createMotionTransaction, type MotionLease } from "./motion-transaction";
import type { CadenceMotion } from "./provider";

export type InlinePresenceCommit = {
  present: boolean;
  enter: boolean;
  cm: CadenceMotion;
};

/** Entrance opacity only, on the original group host. Never writes a resting opacity. */
export function createInlineEntrance(node: HTMLElement) {
  const transaction = createMotionTransaction();
  const owner = transaction.register(node);
  let current: InlinePresenceCommit | null = null;
  let lease: MotionLease | null = null;
  let animation: Animation | null = null;
  let alive = true;
  let blocked = false;
  let generation = 0;
  let signature = "";
  const cancel = () => {
    generation++;
    animation?.cancel();
    animation = null;
    lease?.cancel();
    lease = null;
  };
  const settle = () => {
    cancel();
  };
  const callerOpacity = (css = node.ownerDocument.defaultView?.getComputedStyle(node)) => {
    if (!css) return false;
    const family = css.transitionProperty.split(",").map((property) => property.trim());
    const times = css.transitionDuration.split(",").map((time) => Number.parseFloat(time));
    return (
      family.some(
        (property, index) => ["all", "opacity"].includes(property) && (times[index % times.length] ?? 0) > 0,
      ) ||
      (node.getAnimations?.() ?? []).some(
        (handle) =>
          handle !== animation &&
          (handle.effect as KeyframeEffect | null)?.getKeyframes().some((frame) => "opacity" in frame),
      )
    );
  };
  const play = (from?: string, forceImmediate = false) => {
    const input = current;
    if (!alive || !input) return;
    if (!input.present) {
      settle();
      return;
    }
    const parameters = input.cm.parameters(bindMotionParameters(presenceInline, "data.transition/opacity"));
    if (parameters.kind !== "visual") return;
    const clock = parameters.opacity;
    const immediate = forceImmediate || blocked || clock.duration === 0;
    if (
      (immediate && input.present) ||
      !node.isConnected ||
      typeof node.animate !== "function" ||
      (input.present && node.contains(node.ownerDocument.activeElement))
    ) {
      settle();
      return;
    }
    const css = node.ownerDocument.defaultView?.getComputedStyle(node);
    if (!css || css.display === "none" || css.visibility === "hidden") {
      settle();
      return;
    }
    if (callerOpacity(css)) {
      settle();
      return;
    }
    const epoch = ++generation;
    const revision = transaction.revision("presence", input.present, node);
    let handle: Animation | null = null;
    lease = owner.begin(revision, ["opacity"], {}, () => handle?.cancel());
    if (!lease?.current()) return;
    const owned = lease;
    handle = node.animate([{ opacity: from ?? 0 }, { opacity: css.opacity }], {
      duration: motionMilliseconds(immediate ? 0 : Number(clock.duration)),
      delay: motionMilliseconds(immediate ? 0 : Number(clock.delay ?? 0)),
      easing: `cubic-bezier(${input.cm.scope.tokens.ease.out.join(",")})`,
      fill: "both",
    });
    animation = handle;
    void handle.finished.then(
      () => {
        if (
          !alive ||
          !node.isConnected ||
          epoch !== generation ||
          !owned.current() ||
          current?.present !== input.present
        )
          return;
        settle();
      },
      () => {},
    );
    if (immediate) handle.finish();
  };
  const interact = () => {
    if (current?.present) settle();
  };
  for (const event of ["focusin", "pointerdown", "keydown", "click", "beforematch"])
    node.addEventListener(event, interact, true);
  const opacityStyle = () => {
    const style = node.style;
    return JSON.stringify([
      style.opacity,
      style.animation,
      /(?:^|,)\s*(?:all|opacity)\s*(?:,|$)/.test(style.transitionProperty) ? style.transition : "",
      Array.from(style)
        .filter((name) => name.startsWith("--") && !/^--(?:cadence-|motion-|ease-cadence)/.test(name))
        .map((name) => [name, style.getPropertyValue(name)]),
    ]);
  };
  let callerStyle = opacityStyle();
  const observer = new MutationObserver((records) => {
    const next = opacityStyle();
    // Scoped colour clocks and inherited Cadence tokens are another owned
    // family. Only potentially conflicting caller paint revokes this channel.
    if (
      (next !== callerStyle || records.some((record) => record.attributeName !== "style")) &&
      (current?.present || callerOpacity())
    )
      settle();
    callerStyle = next;
  });
  observer.observe(node, { attributes: true, attributeFilter: ["class", "style", "disabled", "aria-disabled"] });
  const unsubscribe = subscribeMotionEnvironment(node.ownerDocument, (environment) => {
    blocked = environment.hidden || environment.immediate;
    if (blocked || (environment.reduced && animation && current?.cm.mode === "full")) {
      settle();
    }
  });
  return {
    commit(input: InlinePresenceCommit) {
      const previous = current;
      current = input;
      // Resolve the exact entrance clock on every committed policy, including native baselines.
      const parameters = input.cm.parameters(bindMotionParameters(presenceInline, "data.transition/opacity"));
      const clock = JSON.stringify(parameters);
      const retime = signature !== clock;
      signature = clock;
      const change = previous ? previous.present !== input.present : input.enter || !input.present;
      if (change) {
        const from = animation ? node.ownerDocument.defaultView?.getComputedStyle(node).opacity : undefined;
        cancel();
        play(from);
      } else if (input.cm.disabled || input.cm.timeScale === 0) {
        settle();
      } else if (retime && animation) {
        const from = node.ownerDocument.defaultView?.getComputedStyle(node).opacity;
        cancel();
        play(from);
      }
    },
    dispose() {
      alive = false;
      cancel();
      owner.dispose();
      observer.disconnect();
      unsubscribe();
      for (const event of ["focusin", "pointerdown", "keydown", "click", "beforematch"])
        node.removeEventListener(event, interact, true);
    },
  };
}

